import {shuffle,recordAnswer,advance,firstAttemptScore,updateProgress} from './engine.mjs';
import {ALL_LECTURES,normalizeConfig,selectedQuestions,createConfiguredSession} from './config.mjs';
const root=document.querySelector('#app');
const KEY='midterm-lab-v1';
const TOPICS=['','Основы','Android','Угрозы','Онтологии','Доступ','Криптография','Cloud и код'];
let data,warning='',view='home';
let state={progress:{},session:null,config:normalizeConfig()};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=id=>data.find(q=>q.id===id);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{warning='Браузер не разрешил сохранение. Текущая сессия продолжится, пока открыта вкладка.'}}
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw?.progress&&typeof raw.progress==='object'&&!Array.isArray(raw.progress)){state.progress=raw.progress;state.session=raw.session||null;state.config=normalizeConfig(raw.config)}}catch{warning='Не удалось прочитать сохранение. Можно начать новый квиз.'}
function shell(body){root.innerHTML=`<main class="app"><header><span class="brand">midterm<span>lab</span></span><span class="course">Mobile Security</span></header>${warning?`<p class="warning" role="status">${esc(warning)}</p>`:''}${body}</main>`;root.querySelector('[data-start]')?.addEventListener('click',start);root.querySelectorAll('[data-choice]').forEach(el=>el.addEventListener('click',()=>answer(el.dataset.choice)));root.querySelector('[data-next]')?.addEventListener('click',next);root.querySelector('[data-resume]')?.addEventListener('click',resume);root.querySelector('[data-restart]')?.addEventListener('click',restart);root.querySelectorAll('[data-lecture]').forEach(el=>el.addEventListener('change',readConfig));root.querySelector('#all-lectures')?.addEventListener('change',e=>{root.querySelectorAll('[data-lecture]').forEach(el=>el.checked=e.target.checked);readConfig()});root.querySelector('#shuffle-questions')?.addEventListener('change',readConfig)}
function home(){const resume=state.session&&!state.session.done;shell(`<section class="welcome"><span class="label">ЛЕКЦИИ 1–7 · 67 ВОПРОСОВ</span><h1>Подготовка<br>к Midterm</h1><p>Выбери лекции и начинай.<br>Ошибёшься — вопрос вернётся через два других.</p><fieldset class="quiz-settings"><legend>Какие вопросы включить?</legend><label class="all-check"><input id="all-lectures" type="checkbox" ${state.config.lectures.length===7?'checked':''}>Все лекции</label><div class="lecture-grid">${ALL_LECTURES.map(n=>`<label class="lecture-choice"><input type="checkbox" data-lecture="${n}" ${state.config.lectures.includes(n)?'checked':''}><span><b>Лекция ${n}</b><small>${TOPICS[n]}</small></span></label>`).join('')}</div><label class="shuffle-check"><input type="checkbox" id="shuffle-questions" ${state.config.shuffle?'checked':''}>Перемешать вопросы</label><p class="settings-hint">Лекции 3 и 4 — в общей презентации; вопросы разделены по темам. Варианты ответов перемешиваются всегда.</p></fieldset><p class="selected-count" id="selected-count"></p><button class="primary" data-start>Начать экзамен <span aria-hidden="true">→</span></button>${resume?`<button class="resume-button" data-resume>Продолжить сохранённый тест · ${new Set(state.session.answers.map(a=>a.id)).size} из ${state.session.total}</button>`:''}</section>`);updateSelection()}
function start(){const session=createConfiguredSession(data,state.config);if(!session)return;state.session=session;view='quiz';save();render();window.scrollTo(0,0)}
function resume(){if(!state.session||state.session.done)return;view='quiz';render();window.scrollTo(0,0)}
function restart(){state.config=normalizeConfig(state.session?.config||state.config);view='home';save();render();window.scrollTo(0,0)}
function updateSelection(){const count=selectedQuestions(data,state.config).length;root.querySelector('#selected-count').textContent=count?`Вопросов в тесте: ${count}`:'Выбери хотя бы одну лекцию';root.querySelector('[data-start]').disabled=!count;const all=root.querySelector('#all-lectures');all.checked=state.config.lectures.length===7;all.indeterminate=state.config.lectures.length>0&&state.config.lectures.length<7}
function readConfig(){state.config={lectures:[...root.querySelectorAll('[data-lecture]:checked')].map(el=>Number(el.dataset.lecture)),shuffle:root.querySelector('#shuffle-questions').checked};save();updateSelection()}
function source(q){return q.sources.map(s=>`${esc(s.file)} · слайд${s.slides.length>1?'ы':''} ${s.slides.join(', ')}`).join(' / ')}
function quiz(){const s=state.session;if(s.done){result();return}const q=byId(s.queue[s.index]);if(!s.options.length){s.options=shuffle(q.options.map(o=>o.id));save()}const answered=s.current;const completed=new Set(s.answers.map(a=>a.id)).size;const remaining=s.queue.length-s.index-(answered?1:0);const repeat=s.answers.slice(0,answered?-1:undefined).some(a=>a.id===q.id);shell(`<section class="quiz"><div class="quiz-tools"><button class="restart-button" data-restart>↻ Начать заново</button></div><div class="progress-meta"><span>Пройдено ${completed} из ${s.total}</span><span>Лекция ${q.lecture}</span></div><div class="progress" role="progressbar" aria-label="Пройденные вопросы" aria-valuenow="${completed}" aria-valuemin="0" aria-valuemax="${s.total}"><span style="width:${Math.round(completed/s.total*100)}%"></span></div><article class="question"><div class="label">${repeat?'↻ ПОВТОР ВОПРОСА':'ВОПРОС'} · SAMPLE №${q.number}</div><h1>${esc(q.question)}</h1><div class="options">${s.options.map((id,i)=>{const o=q.options.find(o=>o.id===id);const right=answered&&id===q.correct,wrong=answered&&id===answered.choice&&!answered.correct;return `<button class="option ${right?'correct':''} ${wrong?'wrong':''}" data-choice="${id}" ${answered?'disabled':''}><span class="letter">${i+1}</span><span>${esc(o.text)}</span>${right?'<span class="mark" aria-label="Правильный ответ">✓</span>':wrong?'<span class="mark" aria-label="Неверный ответ">×</span>':''}</button>`}).join('')}</div>${answered?`<section class="feedback ${answered.correct?'':'error'}" role="status" aria-label="Объяснение ответа"><strong>${answered.correct?'✓ Правильно':'↻ Неверно — запомним'}</strong>${!answered.correct?`<p class="right-answer">Правильный ответ: <b>${esc(q.options.find(o=>o.id===q.correct).text)}</b></p>`:''}<p>${esc(q.explanation)}</p>${q.note?`<p class="note">${esc(q.note)}</p>`:''}<details class="mnemonic"><summary>Ассоциация для запоминания</summary><p>${esc(q.mnemonic)}</p></details><p class="source">${source(q)}</p>${q.external?`<a class="source" href="${esc(q.external)}" target="_blank" rel="noopener noreferrer">Источник уточнения ↗</a>`:''}${!answered.correct?'<p class="repeat-hint">Вопрос вернётся через два других. Если очередь заканчивается — раньше.</p>':''}</section>`:''}<div class="next-wrap"><button class="primary" data-next ${answered?'':'disabled'}>${answered&&remaining===0?'Завершить':'Следующий вопрос'} <span aria-hidden="true">→</span></button></div>${!answered?'<p class="quiet">Выбери один из четырёх вариантов</p>':''}</article></section>`)}
function answer(choice){if(view!=='quiz')return;const s=state.session;if(s.done||s.current)return;const q=byId(s.queue[s.index]);if(!q.options.some(o=>o.id===choice))return;if(recordAnswer(s,q,choice)){state.progress=updateProgress(state.progress,q.id,choice===q.correct);save();render();root.querySelector('.feedback')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})}}
function next(){if(view!=='quiz'||!advance(state.session))return;if(state.session.done)state.session.finishedAt=Date.now();save();render();window.scrollTo({top:0,behavior:'instant'})}
function result(){const s=state.session,score=firstAttemptScore(s.answers);shell(`<section class="welcome"><span class="label">ЭКЗАМЕН ЗАВЕРШЁН</span><h1>Все вопросы<br>пройдены.</h1><p>С первого раза: <b>${score.correct} из ${score.total}</b>.<br>Все неверные ответы повторены и закреплены.</p><button class="primary" data-restart>Начать заново <span aria-hidden="true">→</span></button><small>Можно выбрать лекции и порядок вопросов.</small></section>`)}
function render(){if(view==='quiz')quiz();else home()}
function validSession(s){return s&&s.mode==='practice'&&Number.isInteger(s.total)&&s.total>0&&s.total<=data.length&&Array.isArray(s.queue)&&s.queue.every(id=>byId(id))&&new Set(s.queue).size===s.total&&Number.isInteger(s.index)&&s.index>=0&&s.index<=s.queue.length&&Array.isArray(s.answers)&&s.answers.every(a=>byId(a.id)&&typeof a.correct==='boolean')&&Array.isArray(s.history)&&Array.isArray(s.options)&&s.options.every(id=>['0','1','2','3'].includes(id))&&(s.current===null||typeof s.current==='object')}
try{const res=await fetch('questions.json');if(!res.ok)throw Error();data=await res.json();if(!validSession(state.session))state.session=null;render()}catch{root.innerHTML='<p class="loading" role="alert">Не удалось загрузить вопросы. Проверь подключение и обнови страницу.</p>'}
// Preserve existing sessions, including quizzes limited to selected lectures.
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.repeat||view!=='quiz'||!state.session||state.session.done)return;const s=state.session;if(/^[1-4]$/.test(e.key)&&!s.current){e.preventDefault();answer(s.options[Number(e.key)-1])}else if(e.key==='Enter'&&s.current&&e.target.tagName!=='BUTTON'){e.preventDefault();next()}});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
